#!/usr/bin/env bash
# Generates core/src/gx/pica/gxpass.v.pica, the GX backend's vertex shader: eight unrolled light blocks (picasso has
# no macros). The maths is gx/vfast.c's vfast_gpu_light_model, which VFAST_CHECK compares with the reference.
#   bash core/tools/gen_gxpass.sh
set -euo pipefail
out="$(dirname "$0")/../src/gx/pica/gxpass.v.pica"
{
cat <<'EOF'
; gc3ds GX backend vertex shader (generated by core/tools/gen_gxpass.sh; edit that).
; Vertices arrive transformed on the CPU (gx/vfast.c): v0 clip position, v1 colour (u8x4), v2-v4 texture coordinates.
; With lon.z = 1 the shader lights the colour channel the PICA receives, from the eight GX lights, exactly as
; vfast_gpu_light_model (the C model the PC checks against the reference), for the cases vfast_gpu_light sends: colour
; half lit with attenuation none or spot, alpha half unlit or lit as the colour half. v1 is then the raw vertex colour, v5 the
; eye-space position and v6 the eye-space normal (normalised here). Uniform layout: VLightUniforms in gx/vfast.h.

.fvec lights[40]
.fvec lsel[4]
.fvec lmat, lamb, lvsel, lon  ; lon: (colour half lit, alpha half lit, light this batch, 0)


.constf myconst(0.0, 1.0, 0.00392156862745098, 1.0e18)
.alias  zeros  myconst.xxxx
.alias  ones   myconst.yyyy
.alias  inv255 myconst.zzzz
.alias  big    myconst.wwww  ; reciprocals are clamped to +-big: an unused term must stay finite so that 0 * it is 0

.out outpos position
.out outclr color
.out outtc0 texcoord0
.out outtc1 texcoord1
.out outtc2 texcoord2

.proc main
	mov outpos, v0
	mov outtc0, v2
	mov outtc1, v3
	mov outtc2, v4
	mul r15, inv255, v1
	; lon.z = 1: the shader lights this batch (a float flag tested with cmp; a bool uniform did not reach the shader)
	mov r14, ones
	cmp lon.zzzz, eq, eq, r14
	ifc cmp.x
	mov r10.xyz, v6
	mov r10.w, zeros
	dp3 r0.x, r10, r10
	rsq r0.x, r0.x
	min r0.x, big, r0.x
	mul r10.xyz, r10.xyz, r0.xxxx
	mov r11, zeros
EOF
for i in 0 1 2 3 4 5 6 7; do
    P=$((5 * i)); D=$((P + 1)); C=$((P + 2)); A=$((P + 3)); K=$((P + 4))
    cat <<EOF2
	; ---- light $i: L, distance, diffuse, spot attenuation (vfast_gpu_light only sends attenuation none or spot, and an
	; alpha half that is unlit or lit exactly as the colour half, so one factor lights all four components)
	add r0, lights[$P], -v5
	dp3 r1.x, r0, r0
	rsq r1.y, r1.x
	min r1.y, big, r1.y
	mul r1.z, r1.x, r1.y
	mul r0, r0, r1.yyyy
	dp3 r2.x, r10, r0
	max r2.y, zeros, r2.x
	dp3 r2.z, -lights[$D], r0
	mov r3.x, ones
	mov r3.y, r2.z
	mul r3.z, r2.z, r2.z
	dp3 r4.x, lights[$A], r3
	max r4.x, zeros, r4.x
	mov r5.x, ones
	mov r5.y, r1.z
	mov r5.z, r1.x
	dp3 r4.y, lights[$K], r5
	rcp r7.x, r4.y
	min r7.x, big, r7.x
	max r7.x, -big, r7.x
	mul r7.z, r4.x, r7.x
	mov r8.x, ones
	mov r8.y, r2.x
	mov r8.z, r2.y
	mov r9.x, ones
	mov r9.y, r7.z
	mov r9.z, zeros
	dp3 r12.x, lsel[0], r8
	dp3 r12.y, lsel[1], r9
	mul r13.x, r12.x, r12.y
	mul r13.x, lights[$A].wwww, r13.x
	mad r11, r13.xxxx, lights[$C], r11
EOF2
done
cat <<'EOF'
	; material and ambient from the register or the vertex colour; lit halves clamp ambient + lights to 0..1
	add r0, -lmat, r15
	mul r1, lvsel.xxxy, r0
	add r1, lmat, r1
	add r0, -lamb, r15
	mul r2, lvsel.zzzw, r0
	add r2, lamb, r2
	add r3, r2, r11
	max r3, zeros, r3
	min r3, ones, r3
	add r3, -ones, r3
	mul r3, lon.xxxy, r3
	add r3, ones, r3
	mul outclr, r1, r3
	.else
	mov outclr, r15
	.end
	end
.end
EOF
} > "$out"
echo "wrote $out ($(grep -c . "$out") lines)"
